## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "beeftv.plugin/v3",
  "id": "vllm-omni-videos",
  "name": "vLLM-Omni Videos · multipart",
  "version": "1.0.0",
  "author": "BeefTV Contributors",
  "description": "vLLM-Omni /v1/videos multipart 异步视频生成协议插件（支持 width/height/aspect_ratio、extra_params、input_references 与 /content 下载）。",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": false
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "vllm-omni-videos",
        "label": "vLLM-Omni Videos · multipart",
        "capabilities": [
          "video"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "http://127.0.0.1:8000",
        "requiresPublicMediaUrls": false,
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "vLLM-Omni 服务端模型 ID（如 minimax-h3-fl2va）。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "视频提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "input_reference / input_references",
            "description": "单图或首尾帧/多参考图片文件上传。"
          },
          {
            "name": "videos",
            "type": "media[]",
            "required": false,
            "mapping": "input_reference / input_references",
            "description": "参考视频文件上传。"
          },
          {
            "name": "audios",
            "type": "media[]",
            "required": false,
            "mapping": "audio_reference",
            "description": "参考音频 JSON 引用（audio_url）。"
          },
          {
            "name": "duration",
            "type": "integer",
            "required": false,
            "mapping": "extra_params.duration",
            "description": "输出时长秒数。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "width / height / aspect_ratio",
            "description": "画幅比例或 WIDTHxHEIGHT 像素尺寸。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "width / height",
            "description": "输出分辨率档位（480p/576p/720p/768p/1080p/1440p）。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "fps / num_inference_steps / flow_shift / seed / extra_params",
            "description": "插件命名空间内的扩展采样与任务参数。"
          }
        ],
        "variables": [
          {
            "name": "resNorm",
            "value": {
              "$lower": {
                "$trim": {
                  "$ref": "request.resolution"
                }
              }
            }
          },
          {
            "name": "ratioNorm",
            "value": {
              "$lower": {
                "$trim": {
                  "$ref": "request.aspectRatio"
                }
              }
            }
          },
          {
            "name": "sizeParts",
            "value": {
              "$split": [
                {
                  "$ref": "vars.ratioNorm"
                },
                "x"
              ]
            }
          },
          {
            "name": "isWxH",
            "value": {
              "$eq": [
                {
                  "$len": {
                    "$ref": "vars.sizeParts"
                  }
                },
                2
              ]
            }
          },
          {
            "name": "normalizedRatio",
            "value": {
              "$switch": {
                "cases": [
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.ratioNorm"
                        },
                        [
                          "16:9",
                          "landscape"
                        ]
                      ]
                    },
                    "then": "16:9"
                  },
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.ratioNorm"
                        },
                        [
                          "9:16",
                          "portrait"
                        ]
                      ]
                    },
                    "then": "9:16"
                  },
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.ratioNorm"
                        },
                        [
                          "1:1",
                          "square"
                        ]
                      ]
                    },
                    "then": "1:1"
                  },
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.ratioNorm"
                        },
                        [
                          "4:3",
                          "3:4",
                          "21:9"
                        ]
                      ]
                    },
                    "then": {
                      "$ref": "vars.ratioNorm"
                    }
                  }
                ],
                "default": null
              }
            }
          },
          {
            "name": "ratioField",
            "value": {
              "$coalesce": [
                {
                  "$ref": "request.providerOptions.vllm-omni-videos.aspect_ratio"
                },
                {
                  "$ref": "vars.normalizedRatio"
                }
              ]
            }
          },
          {
            "name": "targetShort",
            "value": {
              "$switch": {
                "cases": [
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.resNorm"
                        },
                        [
                          "480",
                          "480p",
                          "540",
                          "540p",
                          "576",
                          "576p"
                        ]
                      ]
                    },
                    "then": 576
                  },
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.resNorm"
                        },
                        [
                          "1080",
                          "1080p"
                        ]
                      ]
                    },
                    "then": 1080
                  },
                  {
                    "when": {
                      "$in": [
                        {
                          "$ref": "vars.resNorm"
                        },
                        [
                          "1440",
                          "1440p",
                          "2k"
                        ]
                      ]
                    },
                    "then": 1440
                  }
                ],
                "default": 768
              }
            }
          },
          {
            "name": "ratioParts",
            "value": {
              "$if": {
                "condition": {
                  "$ref": "vars.normalizedRatio"
                },
                "then": {
                  "$split": [
                    {
                      "$ref": "vars.normalizedRatio"
                    },
                    ":"
                  ]
                },
                "else": [
                  1,
                  1
                ]
              }
            }
          },
          {
            "name": "ratioW",
            "value": {
              "$toFloat": {
                "$at": [
                  {
                    "$ref": "vars.ratioParts"
                  },
                  0
                ]
              }
            }
          },
          {
            "name": "ratioH",
            "value": {
              "$toFloat": {
                "$at": [
                  {
                    "$ref": "vars.ratioParts"
                  },
                  1
                ]
              }
            }
          },
          {
            "name": "ratioMin",
            "value": {
              "$min": [
                {
                  "$ref": "vars.ratioW"
                },
                {
                  "$ref": "vars.ratioH"
                }
              ]
            }
          },
          {
            "name": "inferredWidth",
            "value": {
              "$if": {
                "condition": {
                  "$ref": "vars.isWxH"
                },
                "then": {
                  "$toInt": {
                    "$at": [
                      {
                        "$ref": "vars.sizeParts"
                      },
                      0
                    ]
                  }
                },
                "else": {
                  "$if": {
                    "condition": {
                      "$ref": "vars.normalizedRatio"
                    },
                    "then": {
                      "$ceilStep": [
                        {
                          "$divide": [
                            {
                              "$multiply": [
                                {
                                  "$ref": "vars.targetShort"
                                },
                                {
                                  "$ref": "vars.ratioW"
                                }
                              ]
                            },
                            {
                              "$ref": "vars.ratioMin"
                            }
                          ]
                        },
                        32
                      ]
                    },
                    "else": null
                  }
                }
              }
            }
          },
          {
            "name": "inferredHeight",
            "value": {
              "$if": {
                "condition": {
                  "$ref": "vars.isWxH"
                },
                "then": {
                  "$toInt": {
                    "$at": [
                      {
                        "$ref": "vars.sizeParts"
                      },
                      1
                    ]
                  }
                },
                "else": {
                  "$if": {
                    "condition": {
                      "$ref": "vars.normalizedRatio"
                    },
                    "then": {
                      "$ceilStep": [
                        {
                          "$divide": [
                            {
                              "$multiply": [
                                {
                                  "$ref": "vars.targetShort"
                                },
                                {
                                  "$ref": "vars.ratioH"
                                }
                              ]
                            },
                            {
                              "$ref": "vars.ratioMin"
                            }
                          ]
                        },
                        32
                      ]
                    },
                    "else": null
                  }
                }
              }
            }
          },
          {
            "name": "orderedVisualRefs",
            "value": {
              "$concatArrays": [
                {
                  "$sortByOrder": {
                    "$ref": "request.images"
                  }
                },
                {
                  "$sortByOrder": {
                    "$ref": "request.videos"
                  }
                }
              ]
            }
          },
          {
            "name": "useMultiRefs",
            "value": {
              "$or": [
                {
                  "$gt": [
                    {
                      "$len": {
                        "$ref": "vars.orderedVisualRefs"
                      }
                    },
                    1
                  ]
                },
                {
                  "$and": [
                    {
                      "$eq": [
                        {
                          "$len": {
                            "$ref": "vars.orderedVisualRefs"
                          }
                        },
                        1
                      ]
                    },
                    {
                      "$or": [
                        {
                          "$gt": [
                            {
                              "$len": {
                                "$ref": "request.audios"
                              }
                            },
                            0
                          ]
                        },
                        {
                          "$eq": [
                            {
                              "$ref": "request.operation"
                            },
                            "reference_to_video"
                          ]
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "taskType",
            "value": {
              "$coalesce": [
                {
                  "$ref": "request.providerOptions.vllm-omni-videos.task"
                },
                {
                  "$switch": {
                    "cases": [
                      {
                        "when": {
                          "$or": [
                            {
                              "$gt": [
                                {
                                  "$len": {
                                    "$ref": "request.videos"
                                  }
                                },
                                0
                              ]
                            },
                            {
                              "$gt": [
                                {
                                  "$len": {
                                    "$ref": "request.audios"
                                  }
                                },
                                0
                              ]
                            },
                            {
                              "$eq": [
                                {
                                  "$ref": "request.operation"
                                },
                                "reference_to_video"
                              ]
                            },
                            {
                              "$gt": [
                                {
                                  "$len": {
                                    "$filter": {
                                      "from": {
                                        "$ref": "request.images"
                                      },
                                      "as": "media",
                                      "where": {
                                        "$in": [
                                          {
                                            "$ref": "media.role"
                                          },
                                          [
                                            "reference_image",
                                            "subject_reference",
                                            "style_reference"
                                          ]
                                        ]
                                      }
                                    }
                                  }
                                },
                                0
                              ]
                            }
                          ]
                        },
                        "then": "ref2va"
                      },
                      {
                        "when": {
                          "$gt": [
                            {
                              "$len": {
                                "$ref": "request.images"
                              }
                            },
                            0
                          ]
                        },
                        "then": "fl2va"
                      }
                    ],
                    "default": "t2va"
                  }
                }
              ]
            }
          },
          {
            "name": "extraParamsObj",
            "value": {
              "$merge": [
                {
                  "task": {
                    "$ref": "vars.taskType"
                  },
                  "duration": {
                    "$if": {
                      "condition": {
                        "$gt": [
                          {
                            "$ref": "request.duration"
                          },
                          0
                        ]
                      },
                      "then": {
                        "$ref": "request.duration"
                      },
                      "else": null
                    }
                  },
                  "audio_flow_shift": {
                    "$omitEmpty": {
                      "$ref": "request.providerOptions.vllm-omni-videos.audio_flow_shift"
                    }
                  }
                },
                {
                  "$coalesce": [
                    {
                      "$ref": "request.providerOptions.vllm-omni-videos.extra_params"
                    },
                    {}
                  ]
                }
              ]
            }
          }
        ],
        "create": {
          "method": "POST",
          "path": "/v1/videos",
          "contentType": "multipart/form-data",
          "body": {
            "model": {
              "$ref": "request.model"
            },
            "prompt": {
              "$ref": "request.prompt"
            },
            "width": {
              "$omitEmpty": {
                "$coalesce": [
                  {
                    "$ref": "request.providerOptions.vllm-omni-videos.width"
                  },
                  {
                    "$ref": "vars.inferredWidth"
                  }
                ]
              }
            },
            "height": {
              "$omitEmpty": {
                "$coalesce": [
                  {
                    "$ref": "request.providerOptions.vllm-omni-videos.height"
                  },
                  {
                    "$ref": "vars.inferredHeight"
                  }
                ]
              }
            },
            "aspect_ratio": {
              "$omitEmpty": {
                "$ref": "vars.ratioField"
              }
            },
            "seconds": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.seconds"
              }
            },
            "fps": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.fps"
              }
            },
            "num_frames": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.num_frames"
              }
            },
            "num_inference_steps": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.num_inference_steps"
              }
            },
            "guidance_scale": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.guidance_scale"
              }
            },
            "guidance_scale_2": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.guidance_scale_2"
              }
            },
            "flow_shift": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.flow_shift"
              }
            },
            "seed": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.seed"
              }
            },
            "negative_prompt": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.vllm-omni-videos.negative_prompt"
              }
            },
            "lora": {
              "$omitEmpty": {
                "$if": {
                  "condition": {
                    "$ref": "request.providerOptions.vllm-omni-videos.lora"
                  },
                  "then": {
                    "$json": {
                      "$ref": "request.providerOptions.vllm-omni-videos.lora"
                    }
                  },
                  "else": null
                }
              }
            },
            "audio_reference": {
              "$omitEmpty": {
                "$if": {
                  "condition": {
                    "$gt": [
                      {
                        "$len": {
                          "$ref": "request.audios"
                        }
                      },
                      0
                    ]
                  },
                  "then": {
                    "$json": {
                      "audio_url": {
                        "$first": {
                          "$map": {
                            "from": {
                              "$sortByOrder": {
                                "$ref": "request.audios"
                              }
                            },
                            "as": "media",
                            "in": {
                              "$ref": "media.value"
                            }
                          }
                        }
                      }
                    }
                  },
                  "else": null
                }
              }
            },
            "extra_params": {
              "$if": {
                "condition": {
                  "$gt": [
                    {
                      "$len": {
                        "$ref": "vars.extraParamsObj"
                      }
                    },
                    0
                  ]
                },
                "then": {
                  "$json": {
                    "$ref": "vars.extraParamsObj"
                  }
                },
                "else": null
              }
            }
          },
          "files": [
            {
              "name": "input_reference",
              "source": {
                "$if": {
                  "condition": {
                    "$and": [
                      {
                        "$eq": [
                          {
                            "$len": {
                              "$ref": "vars.orderedVisualRefs"
                            }
                          },
                          1
                        ]
                      },
                      {
                        "$not": {
                          "$ref": "vars.useMultiRefs"
                        }
                      }
                    ]
                  },
                  "then": {
                    "$first": {
                      "$ref": "vars.orderedVisualRefs"
                    }
                  },
